import React, { useEffect, useState } from "react";
import { ref, onValue } from "firebase/database";
import { database } from "../firebaseConfig";
import Sidebar from "../compornents/Sidebar";

export default function AdminDashboard() {
  const [reports, setReports] = useState([]);
  const [filteredReports, setFilteredReports] = useState([]);
  const [selectedReport, setSelectedReport] = useState(null);
  const [searchTerm, setSearchTerm] = useState("");
  const [filterStatus, setFilterStatus] = useState("all");

  // 🔥 Realtime data fetching
  useEffect(() => {
    const reportsRef = ref(database, "breakdowns");
    const unsubscribe = onValue(reportsRef, (snapshot) => {
      if (snapshot.exists()) {
        const data = snapshot.val();
        const formatted = Object.keys(data).map((key) => ({
          id: key,
          ...data[key],
        }));
        setReports(formatted.reverse()); // newest first
        setFilteredReports(formatted.reverse());
      } else {
        setReports([]);
        setFilteredReports([]);
      }
    });
    return () => unsubscribe();
  }, []);

  // 🔍 Search + Filter
  useEffect(() => {
    let filtered = [...reports];
    if (filterStatus !== "all") {
      filtered = filtered.filter((r) => r.status === filterStatus);
    }
    if (searchTerm.trim() !== "") {
      filtered = filtered.filter((r) =>
        r.message.toLowerCase().includes(searchTerm.toLowerCase())
      );
    }
    setFilteredReports(filtered);
  }, [searchTerm, filterStatus, reports]);

  return (
    <div className="flex h-screen bg-black text-white font-display">
      <Sidebar />

      {/* Main Content */}
      <main className="flex-1 flex flex-col overflow-hidden">
        {/* Header */}
        <header className="flex flex-wrap justify-between items-center gap-4 p-6 border-b border-gray-700 bg-gray-900">
          <div className="flex flex-col gap-1">
            <p className="text-2xl font-bold tracking-tight">New/Pending Reports</p>
            <p className="text-sm text-gray-400">
              Real-time view of all incoming system breakdown reports.
            </p>
          </div>
          <div className="flex items-center gap-4">
            <button
              className="flex items-center justify-center rounded-lg h-10 px-4 bg-gray-800 hover:bg-gray-700 text-sm font-bold"
              onClick={() => window.location.reload()}
            >
              <span className="material-symbols-outlined mr-2">refresh</span>
              Refresh
            </button>
          </div>
        </header>

        {/* Body */}
        <div className="flex flex-1 overflow-hidden">
          {/* Reports List */}
          <div className="w-1/3 border-r border-gray-700 overflow-y-auto p-4 flex flex-col gap-4 bg-gray-900">
            {/* Filter & Search */}
            <div className="flex items-center gap-2 mb-3">
              <select
                className="bg-gray-800 border border-gray-700 rounded-lg p-2 text-sm"
                value={filterStatus}
                onChange={(e) => setFilterStatus(e.target.value)}
              >
                <option value="all">All</option>
                <option value="pending">Pending</option>
                <option value="approved">Approved</option>
                <option value="in-progress">In Progress</option>
                <option value="resolved">Resolved</option>
              </select>

              <input
                type="text"
                placeholder="Search..."
                className="bg-gray-800 border border-gray-700 rounded-lg p-2 text-sm flex-1"
                value={searchTerm}
                onChange={(e) => setSearchTerm(e.target.value)}
              />
            </div>

            {filteredReports.length > 0 ? (
              filteredReports.map((report) => (
                <div
                  key={report.id}
                  onClick={() => setSelectedReport(report)}
                  className={`bg-gray-800 rounded-lg p-4 cursor-pointer hover:bg-gray-700 ${
                    selectedReport?.id === report.id ? "ring-2 ring-blue-500" : ""
                  }`}
                >
                  <div className="flex justify-between items-start">
                    <p className="font-bold">#{report.id.slice(-5)}</p>
                    <span
                      className={`px-2 py-1 text-xs rounded-full ${
                        report.status === "pending"
                          ? "bg-yellow-500 text-black"
                          : report.status === "approved"
                          ? "bg-green-500 text-black"
                          : "bg-gray-500 text-white"
                      }`}
                    >
                      {report.status}
                    </span>
                  </div>
                  <p className="mt-1 text-sm font-medium">{report.itemName}</p>
                  <p className="mt-1 text-sm font-medium">{report.message}</p>
                  <div className="flex justify-between items-center mt-2 text-xs text-gray-400">
                    <p>{report.reporterName}</p>
                    <p>
                      {report.timestamps?.created
                        ? new Date(report.timestamps.created).toLocaleTimeString()
                        : "N/A"}
                    </p>
                  </div>
                </div>
              ))
            ) : (
              <p className="text-gray-400 text-sm mt-4 text-center">
                No reports found.
              </p>
            )}
          </div>

          {/* Report Detail Panel */}
          <div className="w-2/3 overflow-y-auto p-6 bg-gray-900">
            {selectedReport ? (
              <div className="flex flex-col gap-6">
                <div>
                  <div className="flex justify-between items-center">
                    <h2 className="text-xl font-bold">
                      Report #{selectedReport.id.slice(-5)}
                    </h2>
                    <div className="flex gap-2">
                      <button className="rounded-lg h-10 px-4 bg-green-500 text-white text-sm font-bold hover:bg-green-600">
                        Approve
                      </button>
                      <button className="rounded-lg h-10 px-4 bg-blue-500 text-white text-sm font-bold hover:bg-blue-600">
                        Assign Technician
                      </button>
                    </div>
                  </div>
                 
                  <p className="text-lg font-semibold mt-2">
                    {selectedReport.message}
                  </p>
                </div>

                <div className="grid grid-cols-2 gap-6">
                  <div>
                    <h3 className="text-sm font-medium text-gray-400">User Details</h3>
                    <p className="mt-1">{selectedReport.reporterName}</p>
                    <p>{selectedReport.reporterEmail}</p>
                  </div>
                  <div>
                    <h3 className="text-sm font-medium text-gray-400">Status</h3>
                    <p className="mt-1 capitalize">{selectedReport.status}</p>
                  </div>
                </div>

                <div>
                  <h3 className="text-sm font-medium text-gray-400">Full Report</h3>
                  <p className="mt-1 leading-relaxed">
                    {selectedReport.description || "No detailed description available."}
                  </p>
                </div>

                <div className="border-t border-gray-700 pt-6">
                  <h3 className="text-lg font-bold mb-4">Activity & Updates</h3>
                  <div className="flex items-start gap-4">
                    <select className="w-1/3 rounded-lg bg-gray-800 border-none text-white focus:ring-primary">
                      <option>New</option>
                      <option>Pending</option>
                      <option>Approved</option>
                      <option>In Progress</option>
                      <option>Resolved</option>
                      <option>Closed</option>
                    </select>
                    <textarea
                      className="w-2/3 rounded-lg bg-gray-800 border-none text-white focus:ring-primary"
                      placeholder="Add update..."
                      rows="2"
                    />
                  </div>
                  <div className="flex justify-end gap-2 mt-4">
                    <button className="rounded-lg h-10 px-4 bg-blue-500 text-white text-sm font-bold">
                      Add Update
                    </button>
                    <button className="rounded-lg h-10 px-4 bg-red-500 text-white text-sm font-bold">
                      Close Report
                    </button>
                  </div>
                </div>
              </div>
            ) : (
              <p className="text-gray-400 text-center mt-20">
                Select a report to view details.
              </p>
            )}
          </div>
        </div>
      </main>
    </div>
  );
}
